Select * from customer
limit 30;

--Q1. What is the total revenue generated by male vs. female customers?

Select gender,
SUM(purchase_amount) as revenue
from customer
GROUP by 1;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 

Select  customer_id,
		purchase_amount
from customer
Where discount_applied = 'Yes'
and purchase_amount > (Select avg(purchase_amount) from customer);



--if we wish to show the avg alongside as well **
--Select customer_id,purchase_amount,
--(Select avg(purchase_amount) from customer) as avg_purchase
--from customer

-- Q3. Which are the top 5 products with the highest average review rating?

Select item_purchased as product,
		round(AVG(review_rating::numeric),2) as avg_review_rating
From customer
GROUP BY 1 
ORDER BY avg_review_rating desc
LIMIT 5;


--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 

Select shipping_type,
		AVG(purchase_amount)
From customer
Where shipping_type in ('Standard','Express')
GROUP BY 1;


--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.

Select subscription_status,
AVG(purchase_amount) as avg_spend,
SUM(purchase_amount) as total_revenue
From customer
Group by 1 ;


--Q6. Which 5 products have the highest percentage of purchases with discounts applied?

Select item_purchased,
	   COUNT(item_purchased) as total_items_purchased,
	   SUM(CASE
	   WHen discount_applied = 'Yes' then 1
	   else 0
	   end
	   )  as discounted_purchases,
	   ROUND(100.0 * SUM (CAse
	   when discount_applied = 'Yes' then 1
	   else 0
	   end)/COUNT(item_purchased),2) as discounted_purchase_percentage
from customer
Group by 1 
Order by discounted_purchase_percentage desc
LIMIT 5 ;


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 

With customer_type as(
Select customer_id,previous_purchases,
CASE WHEN previous_purchases <= 1 then 'new'
when previous_purchases Between 2 and 10 then 'returning'
else 'loyal'
end as Customer_category
from customer
)

Select customer_category,ROUND(AVG(previous_purchases),2) as avg_purchases,
COUNT(customer_id) as total_customers,
COUNT(customer_category)
from customer_type
Group by 1;


--Q8. What are the top 3 most purchased products within each category? 
With ranked as(
Select item_purchased,
		category,
		DENSE_RANK() OVER (Partition by category Order by COUNT(customer_id) desc) as rank
from customer
Group by 2,1
Order by category,rank)

Select *
from ranked
where rank <4;


--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

Select COUNT(customer_id) as repeat_buyers,
subscription_status
from customer
Where previous_purchases >5
Group by 2 ;


--Q10. What is the revenue contribution of each age group? 

Select age,SUM(purchase_amount) as revenue_contribution
from customer
Group by 1 
order by revenue_contribution desc